// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// realClock uses the wall clock.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// The bucket holds up to Burst tokens and refills at Rate tokens per second.
type Limiter struct {
	mu sync.Mutex

	rate   float64 // tokens per second
	burst  float64 // bucket capacity
	tokens float64 // current tokens
	last   time.Time
	clock  Clock
}

var (
	ErrNonPositiveRate  = errors.New("ratelimit: rate must be > 0")
	ErrNonPositiveBurst = errors.New("ratelimit: burst must be > 0")
	ErrNilClock         = errors.New("ratelimit: clock must not be nil")
)

// New creates a Limiter with the given refill rate (tokens/sec) and burst
// capacity. The bucket starts full. Uses the real clock.
func New(rate, burst float64) (*Limiter, error) {
	return NewWithClock(rate, burst, realClock{})
}

// NewWithClock is New with an injectable Clock; clock must not be nil.
func NewWithClock(rate, burst float64, clock Clock) (*Limiter, error) {
	if clock == nil {
		return nil, ErrNilClock
	}
	if rate <= 0 {
		return nil, ErrNonPositiveRate
	}
	if burst <= 0 {
		return nil, ErrNonPositiveBurst
	}
	return &Limiter{
		rate:   rate,
		burst:  burst,
		tokens: burst,
		last:   clock.Now(),
		clock:  clock,
	}, nil
}

// AllowN reports whether n tokens may be consumed at time now.
// If allowed, the tokens are consumed; otherwise the bucket is unchanged.
func (l *Limiter) AllowN(n float64) bool {
	return l.allowN(n, l.clock.Now())
}

// Allow reports whether one token may be consumed.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

func (l *Limiter) allowN(n float64, now time.Time) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = min(l.burst, l.tokens+elapsed*l.rate)
		l.last = now
	}
	if n > l.tokens {
		return false
	}
	l.tokens -= n
	return true
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
