// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// realClock uses the system time.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// The bucket holds up to Burst tokens and refills at Rate tokens per second.
type Limiter struct {
	mu     sync.Mutex
	tokens float64
	last   time.Time
	clock  Clock
	burst  int
	rate   float64 // tokens per second
}

var (
	ErrNonPositiveBurst = errors.New("ratelimit: burst must be > 0")
	ErrNonPositiveRate  = errors.New("ratelimit: rate must be > 0")
	ErrNilClock         = errors.New("ratelimit: clock must not be nil")
)

// New creates a Limiter with the given burst capacity and refill rate
// (tokens per second). The bucket starts full. If clock is nil, the
// real system clock is used.
func New(burst int, rate float64, clock Clock) (*Limiter, error) {
	if burst <= 0 {
		return nil, ErrNonPositiveBurst
	}
	if rate <= 0 {
		return nil, ErrNonPositiveRate
	}
	if clock == nil {
		clock = realClock{}
	}
	return &Limiter{
		tokens: float64(burst),
		last:   clock.Now(),
		clock:  clock,
		burst:  burst,
		rate:   rate,
	}, nil
}

// AllowN reports whether n tokens may be consumed at time now.
// If so, the tokens are removed.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	if now.After(l.last) {
		elapsed := now.Sub(l.last).Seconds()
		l.tokens += elapsed * l.rate
		if l.tokens > float64(l.burst) {
			l.tokens = float64(l.burst)
		}
		l.last = now
	}

	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Allow reports whether one token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

// Burst returns the configured burst capacity.
func (l *Limiter) Burst() int { return l.burst }

// Rate returns the configured refill rate in tokens per second.
func (l *Limiter) Rate() float64 { return l.rate }
