package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock returns a Clock backed by the system time.
func RealClock() Clock { return realClock{} }

// Limiter is a concurrency-safe token-bucket rate limiter.
// It is safe for concurrent use by multiple goroutines.
type Limiter struct {
	mu       sync.Mutex
	rate     float64   // tokens per second
	burst    float64   // bucket capacity
	tokens   float64   // current tokens
	last     time.Time // last refill time
	clock    Clock
}

// ErrInvalidConfig is returned by New for non-positive rate or burst.
var ErrInvalidConfig = errors.New("ratelimit: rate and burst must be positive")

// New creates a Limiter with the given refill rate (tokens per second)
// and burst capacity (maximum tokens). The bucket starts full.
func New(rate, burst float64) (*Limiter, error) {
	return NewWithClock(rate, burst, RealClock())
}

// NewWithClock is like New but accepts an injectable Clock.
func NewWithClock(rate, burst float64, clock Clock) (*Limiter, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: nil clock")
	}
	if rate <= 0 || burst <= 0 {
		return nil, ErrInvalidConfig
	}
	return &Limiter{
		rate:   rate,
		burst:  burst,
		tokens: burst,
		last:   clock.Now(),
		clock:  clock,
	}, nil
}

// Allow reports whether one token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available at time now,
// refilling the bucket based on elapsed time. If allowed, the
// tokens are consumed; otherwise the bucket is left unchanged.
func (l *Limiter) AllowN(n float64) bool {
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = min(l.burst, l.tokens+elapsed*l.rate)
		l.last = now
	}
	if n < 0 || n > l.tokens {
		return false
	}
	l.tokens -= n
	return true
}

// Tokens returns the current number of available tokens.
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	elapsed := l.clock.Now().Sub(l.last).Seconds()
	if elapsed > 0 {
		return min(l.burst, l.tokens+elapsed*l.rate)
	}
	return l.tokens
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
